Decimal decimal_from_real(Real value)
{
    if (!std::isfinite(value))
        throw std::invalid_argument("statusbar: non-finite real value");
    std::ostringstream stream;
    stream << std::setprecision(std::numeric_limits<Real>::max_digits10) << value;
    return Decimal::parse(stream.str());
}

Integer rounded_real_to_integer(Real value, Integer fallback = 0)
{
    if (!std::isfinite(value))
        return fallback;
    // Integer は int64_t である。2^63 は Real
    // では表せても Integer では表せないため、上端を含めない。
    constexpr int integer_bits = std::numeric_limits<Integer>::digits;
    const long double upper = std::ldexp(1.0L, integer_bits);
    const long double rounded = std::round(static_cast<long double>(value));
    if (rounded >= upper)
        return std::numeric_limits<Integer>::max();
    if (rounded < -upper)
        return std::numeric_limits<Integer>::min();
    return static_cast<Integer>(rounded);
}

Integer scale(Integer value)
{
    // ステータスバーの全座標・余白には、小数倍率での int()
    // の切り捨ても含め、共通の Py 互換 cw.s() を使う。
    const auto scaled = ::cw::s(::cw::lib::Value(value));
    return std::get<Integer>(scaled.storage());
}

Integer value_integer(const ::cw::lib::Value& value, Integer fallback = 0)
{
    if (const auto* integer = std::get_if<Integer>(&value.storage()))
        return *integer;
    if (const auto* real = std::get_if<Real>(&value.storage())) {
        if (!std::isfinite(*real))
            return fallback;
        try {
            return decimal_from_real(*real).to_integer(::cw::lib::DecimalRounding::Down);
        } catch (const ::cw::lib::DecimalError&) {
            return fallback;
        }
    }
    if (const auto* decimal = std::get_if<Decimal>(&value.storage())) {
        try {
            return decimal->to_integer(::cw::lib::DecimalRounding::Down);
        } catch (const ::cw::lib::DecimalError&) {
            return fallback;
        }
    }
    if (const auto* boolean = std::get_if<bool>(&value.storage()))
        return *boolean ? 1 : 0;
    if (const auto* text = std::get_if<::cw::lib::String>(&value.storage())) {
        try {
            const auto parsed = Decimal::parse(*text);
            const auto result = parsed.to_integer(::cw::lib::DecimalRounding::Down);
            // 文字列はDecimalの空白・指数表
            // 記を許して解析するが、値が整数と完
            // 全一致する場合だけ整数へ変換する。
            return parsed == Decimal(result) ? result : fallback;
        } catch (const ::cw::lib::DecimalError&) {
            return fallback;
        }
    }
    return fallback;
}

bool area_is(Integer area, const ::cw::lib::Value& value)
{
    return area == value_integer(value, std::numeric_limits<Integer>::min());
}

