void register_statusbar_sprite(const std::shared_ptr<::cw::lib::Object>& sprite)
{
    if (!::cw::g_cwpy || !sprite)
        return;
    const auto owner = std::dynamic_pointer_cast<::cw::sprite::base::CWPySprite>(sprite);
    if (!owner)
        return;
    const Integer layer = std::dynamic_pointer_cast<Desc>(sprite) ? g_LAYER_DESC :
        std::dynamic_pointer_cast<ProgressView>(sprite) ? g_LAYER_STATUS_PROGRESS :
        std::dynamic_pointer_cast<::cw::sprite::touchbutton::TouchButton>(sprite) ? g_LAYER_TOUCH_BUTTON :
        std::dynamic_pointer_cast<VolumeBar>(sprite) ? g_LAYER_VOLUME_BAR :
        std::dynamic_pointer_cast<StatusBar>(sprite) ? g_LAYER_BASE : g_LAYER_STATUS_ITEM;
    owner->m_tlayer = {layer, 0, 0, 0};
    const auto* group = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_sbargrp.storage());
    if (!group || !*group)
        return;
    if (!owner->m_ui_backend)
        owner->m_ui_backend = ::cw::sprite::base::sprite_ui_backend();
    if (owner->m_ui_backend)
        owner->m_ui_backend->register_sprite(*owner, {*group});
}

