void retain_sprite(StatusBar* parent,
                   const std::shared_ptr<::cw::lib::Object>& sprite,
                   bool progress = false)
{
    if (!parent || !sprite)
        return;
    auto& sprites = progress ? parent->m_status_progress : parent->m_status_items;
    // StatusBarButton/Panel が _create_paneimg()
    // 経由で二つ目の非所有参照を登録しないようにする。 StatusBar::change()
    // の所有項目とは shared_ptr の識別が異なり、両
    // 方が残ると実体破棄後に無効な生ポインターを保持してしまう。
    const auto raw = sprite.get();
    const bool already_retained = std::any_of(sprites.begin(), sprites.end(),
        [raw](const std::shared_ptr<::cw::lib::Object>& existing) {
            return existing && existing.get() == raw;
        });
    sprites.erase(std::remove_if(sprites.begin(), sprites.end(),
        [raw](const std::shared_ptr<::cw::lib::Object>& existing) {
            return existing && existing.get() == raw;
        }),
        sprites.end());
    sprites.push_back(sprite);
    const Integer layer = progress ? g_LAYER_STATUS_PROGRESS :
        (std::dynamic_pointer_cast<Desc>(sprite) ? g_LAYER_DESC : g_LAYER_STATUS_ITEM);
    add_backend_layer(layer, {sprite});
    // reset() は保持中のボタン・パネルを移動・再構築する場合がある。 合成
    // レイヤーと実際の SpriteGroup のプロキシーを両方更新し、当たり判
    // 定が layered_draw_ex() と同じ矩形・画像を使うようにする。
    if (already_retained)
        unregister_statusbar_sprite(sprite);
    register_statusbar_sprite(sprite);
}

