void set_host_services(std::shared_ptr<StatusBarHostServices> arg_services)
{
    g_host_services = std::move(arg_services);
}

std::shared_ptr<StatusBarHostServices> host_services()
{
    return g_host_services;
}

std::shared_ptr<::cw::sprite::base::SelectableSprite> find_retained_selectable(
    const StatusBar& bar, const ::cw::sprite::base::SelectableSprite* raw)
{
    if (!raw) return {};
    const auto find = [raw](const auto& objects) {
        for (const auto& object : objects) {
            const auto sprite = std::dynamic_pointer_cast<::cw::sprite::base::SelectableSprite>(object);
            if (sprite && sprite.get() == raw) return sprite;
        }
        return std::shared_ptr<::cw::sprite::base::SelectableSprite>{};
    };
    if (auto sprite = find(bar.m_status_items)) return sprite;
    return find(bar.m_status_progress);
}

std::shared_ptr<::cw::lib::Object> find_retained_statusbar_object(
    const StatusBar& bar, const ::cw::sprite::base::CWPySprite* raw)
{
    if (!raw) return {};
    const auto find = [raw](const auto& objects) {
        for (const auto& object : objects) {
            const auto sprite = std::dynamic_pointer_cast<::cw::sprite::base::CWPySprite>(object);
            if (sprite && sprite.get() == raw) return object;
        }
        return std::shared_ptr<::cw::lib::Object>{};
    };
    if (auto object = find(bar.m_status_items)) return object;
    return find(bar.m_status_progress);
}

void Desc::initialize(::cw::lib::Value arg_parent, ::cw::lib::String arg_name, ::cw::lib::String arg_desc, ::cw::lib::String arg_hotkey, std::optional<::cw::lib::Integer> arg_arrowpos)
{
    ::cw::sprite::base::CWPySprite::initialize({});
    // Python は Desc と親の循環参照を許して GC に委ねるが、
    // C++ は m_parent_typed だけを弱参照にし、ダイアロ
    // グ終了・ステータスバー再構築後に削除された操作部品を保持し続けない。
    m_parent = {};
    m_name = arg_name;
    m_desc = arg_desc;
    m_hotkey = arg_hotkey;
    m_parent_typed.reset();
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&arg_parent.storage()))
        m_parent_typed = object ? *object : nullptr;
    m_name_typed = std::move(arg_name);
    m_desc_typed = std::move(arg_desc);
    m_hotkey_typed = std::move(arg_hotkey);
    m_arrowpos_typed = arg_arrowpos;

    const auto parent_rect = rect_from_parent(m_parent_typed.lock());
    // Py と同様、名前がある場合だけタイトル部分を描く。 ホッ
    // トキーだけでは高さを確保したり区切り線を追加したりしない。
    const auto title = m_name_typed.empty() ? ::cw::lib::String{} :
        (m_hotkey_typed.empty() ? m_name_typed : m_name_typed + "(" + m_hotkey_typed + ")");
    const auto lines = ::cw::lib::encoding::splitlines(m_desc_typed);
    const Integer padding_x = scale(8);
    const Integer padding_y = scale(4);
    auto title_image = title.empty() ? std::shared_ptr<::cw::lib::Surface>{}
        : render_text_surface(title, "sbardesctitle", scale(14), {0, 0, 0, 255}, true);
    std::vector<std::shared_ptr<::cw::lib::Surface>> line_images;
    Integer width = scale(1);
    Integer body_height = 0;
    Integer title_height = 0;
    Integer title_line_height = 0;
    std::vector<Integer> line_heights;
    const auto measure = [](const ::cw::lib::String& text, const ::cw::lib::String& role,
                            Integer points, bool bold,
                            const std::shared_ptr<::cw::lib::Surface>& image) {
        if (g_host_services && g_host_services->measure_text) {
            if (auto metrics = g_host_services->measure_text(text, role, points, bold))
                return *metrics;
        }
        // フォント提供元のない画面なしの呼び出し側では、既存の描画面による
        // 近似を維持する。 製品の両ホストは実際のフォント寸法を供給する。
        return StatusBarHostServices::TextMetrics{
            image ? image->size : ::cw::lib::Size{0, points},
            image ? image->size.height : points};
    };
    if (title_image) {
        const auto metrics = measure(title, "sbardesctitle", scale(14), true, title_image);
        title_height = metrics.size.height;
        title_line_height = metrics.font_height;
        width = std::max(width, metrics.size.width + padding_x * 2);
    }
    for (const auto& line : lines) {
        auto line_image = render_text_surface(line, "sbardesc", scale(12), {0, 0, 0, 255});
        const auto metrics = measure(line, "sbardesc", scale(12), false, line_image);
        width = std::max(width, metrics.size.width + padding_x * 2);
        body_height += metrics.font_height;
        line_heights.push_back(metrics.font_height);
        line_images.push_back(std::move(line_image));
    }
    const Integer height = padding_y * 2 + title_height + body_height + (title.empty() ? 0 : scale(3));
    const Integer arrow_height = scale(12);
    assign_surface(*this, make_surface(width, height + arrow_height, {255, 255, 200, 255}));
    fill_rect(::cw::sprite::base::CWPySprite::m_image,
              {0, height, width, arrow_height}, {255, 255, 200, 0});
    ::cw::setting::Resource::draw_frame(::cw::sprite::base::CWPySprite::m_image,
        std::make_shared<::cw::RectValue>(::cw::lib::Rect{0, 0, width, height}), {0, 0, 0});
    ::cw::sprite::base::CWPySprite::m_rect = {parent_rect.x, parent_rect.y - height - scale(5), width, height + arrow_height};
    if (arg_arrowpos)
        ::cw::sprite::base::CWPySprite::m_rect.x = parent_rect.x + *arg_arrowpos - width / 2;
    else
        // Py の Rect.center への代入と同様、二つの整数の半分を別々に求める。
        ::cw::sprite::base::CWPySprite::m_rect.x = parent_rect.x + parent_rect.width / 2 - width / 2;
    const Integer game_width = scale(std::get<0>(::cw::g_SIZE_GAME));
    // Python と同様、これらの範囲補正を順に適用する。 大きすぎ
    // る説明は左端へ制限せず、負の x も含め最終的に右揃えになる。
    auto& desc_x = ::cw::sprite::base::CWPySprite::m_rect.x;
    if (desc_x < scale(2)) desc_x = scale(2);
    if (desc_x >= game_width - width) desc_x = game_width - scale(2) - width;
    ::cw::sprite::base::CWPySprite::m_rect.y = parent_rect.y - height - scale(5);
    Integer line_y = padding_y;
    if (title_image) {
        blit_surface(::cw::sprite::base::CWPySprite::m_image, title_image, padding_x, line_y);
        line_y += title_line_height + scale(1);
        const Integer separator_width = scale(1);
        // pygame.draw.line と同様、拡縮後の幅がゼロなら何も描かない。
        if (separator_width > 0)
            fill_rect(::cw::sprite::base::CWPySprite::m_image,
                      {padding_x, line_y - (separator_width - 1) / 2,
                       std::max<Integer>(0, width - padding_x * 2 + 1), separator_width},
                      {0, 0, 0, 255});
        line_y += scale(2);
    }
    for (std::size_t i = 0; i < line_images.size(); ++i) {
        if (line_images[i])
            blit_surface(::cw::sprite::base::CWPySprite::m_image, line_images[i], padding_x, line_y);
        line_y += line_heights[i];
    }
    const Integer arrow_center = arg_arrowpos
        ? parent_rect.x + *arg_arrowpos - ::cw::sprite::base::CWPySprite::m_rect.x
        // 画面の境界に合わせて説明枠が動いても、矢印は親を指し続ける。
        : parent_rect.x + parent_rect.width / 2 - ::cw::sprite::base::CWPySprite::m_rect.x;
    // Py と同様、cw.s(8)//2 を使う。小数倍率では cw.s(4) と異なる。
    const Integer arrow_half_width = scale(8) / 2;
    // Py と同様、多角形を描いてから閉じない平滑化線を描く。
    // 下部の帯は矢印外を透明に保ち、最終の RGBA 乗算を
    // 枠・文字と部分的に覆う矢印のピクセルの両方へ適用する。
    const std::vector<::cw::lib::Point> arrow{
        {arrow_center - arrow_half_width, height - 1},
        {arrow_center, height - 1 + arrow_height},
        {arrow_center + arrow_half_width, height - 1}};
    auto& desc_surface = *::cw::sprite::base::CWPySprite::m_image;
    ::cw::lib::pygame_draw::filled_polygon(desc_surface, arrow, {255, 255, 200, 255});
    ::cw::lib::pygame_draw::aalines(desc_surface, arrow, {0, 0, 0, 255}, false);
    ::cw::lib::simd_image::multiply_rgba_alpha(desc_surface.rgba.data(), desc_surface.rgba.size() / 4, 224);
    invalidate_rect(::cw::sprite::base::CWPySprite::m_rect);
}

void ProgressView::initialize(std::shared_ptr<::cw::sprite::statusbar::StatusBar> arg_parent, std::tuple<::cw::lib::Integer, ::cw::lib::Integer> arg_pos, std::optional<std::tuple<::cw::lib::Integer, ::cw::lib::Integer>> arg_size, ::cw::lib::String arg_text, ::cw::lib::Integer arg_nmax, ::cw::lib::Integer arg_nmin, ::cw::lib::Integer arg_current)
{
    if(!arg_parent)throw std::invalid_argument("StatusBar is null");
    ::cw::sprite::base::CWPySprite::initialize({});m_parent=arg_parent;m_text=std::move(arg_text);m_max=arg_nmax;m_min=arg_nmin;m_current=arg_current;m__last_params.reset();
    const auto size=arg_size.value_or(std::tuple<::cw::lib::Integer,::cw::lib::Integer>{scale(300),scale(22)});
    m_rect={arg_parent->m_rect.x+std::get<0>(arg_pos),arg_parent->m_rect.y+std::get<1>(arg_pos),std::get<0>(size),std::get<1>(size)};update_image();
}

void ProgressView::update(const ::cw::lib::Arguments& arg_args, const ::cw::lib::KeywordArguments& arg_kwargs)
{
    (void)arg_args;
    (void)arg_kwargs;
    const auto params = std::make_tuple(m_text, m_max, m_min, m_current);
    if (m__last_params != params) {
        update_image();
        if (::cw::g_cwpy)
            ::cw::g_cwpy->m_has_inputevent = true;
    }
}

void ProgressView::update_image()
{
    if (m_max == m_min)
        throw std::invalid_argument("ProgressView: max and min must differ");
    m__last_params = std::make_tuple(m_text, m_max, m_min, m_current);
    const Integer width = std::max<Integer>(0, m_rect.width);
    const Integer height = std::max<Integer>(0, m_rect.height);
    auto image = make_surface(width, height, {255, 255, 255, 255});
    fill_rect(image, {0, 0, width, height}, {0, 0, 0, 255});
    fill_rect(image, {scale(1), scale(1), std::max<Integer>(0, width - scale(2)),
                      std::max<Integer>(0, height - scale(2))}, {255, 255, 255, 255});
    const Real denominator = static_cast<Real>(m_max) - static_cast<Real>(m_min);
    if (!std::isfinite(denominator) || denominator == 0.0)
        throw std::invalid_argument("ProgressView: max and min must differ by a finite value");
    const Real g = static_cast<Real>(width - scale(2)) / denominator;
    const Integer progress = std::clamp<Integer>(
        trunc_toward_zero(static_cast<Real>(m_current) * g) + scale(1), 0, width);
    fill_rect(image, {scale(1), scale(1), progress, std::max<Integer>(0, height - scale(2))}, {0, 0, 128, 255});
    if (auto text_image = render_text_surface(m_text, "sbarprogress", scale(12), {0, 0, 0, 255})) {
        const Integer max_text_width = std::max<Integer>(0, width - scale(6));
        if (text_image->size.width > max_text_width && max_text_width > 0)
            text_image = resize_surface(text_image, max_text_width, text_image->size.height);
        const Integer text_x = (width - text_image->size.width) / 2;
        const Integer text_y = (height - text_image->size.height) / 2;
        blit_surface(image, text_image, text_x, text_y);
        auto white_text = copy_surface(text_image);
        if (white_text) {
            for (std::size_t i = 0; i + 3 < white_text->rgba.size(); i += 4) {
                if (white_text->rgba[i + 3] != 0)
                    white_text->rgba[i] = white_text->rgba[i + 1] = white_text->rgba[i + 2] = 255;
            }
            blit_surface_clipped(image, white_text, text_x, text_y,
                                 {scale(1), scale(1), progress, std::max<Integer>(0, height - scale(2))});
        }
    }
    _draw_edge(image);
    assign_surface(*this, image);
    invalidate_rect(m_rect);
}

void StatusBar::initialize()
{
    m__init=false;
}

bool StatusBar::is_initialized()
{
    return m__init;
}

void StatusBar::init()
{
    ::cw::sprite::base::CWPySprite::initialize({});m__init=true;m_yadomoney.reset();m_partymoney.reset();m_autostart.reset();m_debugger.reset();m_backlog.reset();m_settings.reset();m_help.reset();m_touchmenu.reset();m_infocards.reset();m_friendcards.reset();m_debuglog.reset();m_status_items.clear();m_status_progress.clear();m_showbuttons=false;m_maskmode.reset();m_loading=false;m_volumebar=std::make_shared<VolumeBar>();m_volumebar->initialize();_init_image();
    add_backend_layer(g_LAYER_BASE, {std::static_pointer_cast<::cw::lib::Object>(m_image)});
}

void StatusBar::_init_image()
{
    m_image = make_surface(scale(632), scale(33), {240, 240, 240, 255});
    m_rect = {0, scale(420), m_image->size.width, m_image->size.height};
    m_maskmode = !m_showbuttons && ::cw::g_cwpy && ::cw::g_cwpy->is_statusbarmask();
    if (::cw::g_cwpy && ::cw::g_cwpy->m_rsrc) {
        if (const auto background = ::cw::g_cwpy->m_rsrc->get_statusbtnbmp(2, 0)) {
            auto subimg = copy_surface(*background);
            if (m_maskmode.value_or(false))
                blend_rgb_sub(subimg, 64);
            blit_surface(m_image, subimg, 0, 0);
        }
    }
}

void StatusBar::update_scale()
{
    if(!m__init)return;_init_image();hide_touchbuttons(true);clear_volumebar();change(m_showbuttons,false);
}

void StatusBar::change(bool arg_showbuttons, bool arg_encounter)
{
    if (!m__init)
        return;

    clear();
    const auto runtime = ::cw::g_cwpy;
    const auto data = system_data();
    const bool in_camp = runtime &&
                         (area_is(runtime->m_areaid, ::cw::g_AREA_CAMP) ||
                          area_is(runtime->m_areaid, ::cw::g_AREA_TRADE3));

    // Python と同様、ネイティブの入力更新フラグ m_has_inputevent ではなく、 予
    // 約済み処理の pygame.USEREVENT 相当を確認する。拡大処理中も引き続きボタンを隠す。
    if (runtime && arg_showbuttons && (has_queued_userevent() || is_expanding()) && !in_camp) {
        arg_showbuttons = false;
    }

    m_showbuttons = arg_showbuttons;
    const bool maskmode = !m_showbuttons && runtime && runtime->is_statusbarmask();
    if (!m_maskmode || *m_maskmode != maskmode) {
        m_maskmode = maskmode;
        _init_image();
    }

    const auto self = parent_alias(this);
    if (runtime && is_expanding()) {
        auto progress = std::make_shared<ExpandView>();
        progress->initialize(self, {scale(10), scale(6)});
        retain_sprite(this, progress, true);
    }

    bool showbuttons = m_showbuttons;
    if (runtime && (runtime->is_showingbacklog() || (data && data->m_in_f9)))
        showbuttons = false;

    Integer left = scale(602);
    Integer rmargin = 0;
    const Integer button_step = scale(28);
    const Integer panel_gap = scale(14);
    const Integer panel_width = scale(120);

    if (runtime && runtime->m_setting && runtime->m_setting->m_show_tiles) {
        _create_touchmenu({left, scale(3)});
        left -= button_step;
        rmargin += button_step;
    } else {
        hide_touchbuttons(true);
    }

    if (!::cw::novel::enabled()) {
        _create_help({left, scale(3)});
        left -= button_step;
        rmargin += button_step;
        _create_settings({left, scale(3)});
    }

    if (runtime && runtime->m_setting && runtime->m_setting->m_backlogmax) {
        left -= button_step;
        rmargin += button_step;
        _create_backlog({left, scale(3)});
    }

    if (runtime && runtime->is_debugmode()) {
        left -= button_step;
        rmargin += button_step;
        _create_debugger({left, scale(3)});
    }

    const auto panel_position = std::tuple<Integer, Integer>{scale(474) - rmargin, scale(6)};
    if (arg_encounter) {
            auto panel = std::make_shared<EncounterPanel>();
            panel->initialize(self, panel_position);
            retain_sprite(this, panel);
            left -= panel_width + panel_gap;
    } else if (runtime &&
               ((runtime->is_curtained() && !area_is(runtime->m_areaid, ::cw::g_AREA_CAMP)) ||
                (runtime->m_selectedheader && *runtime->m_selectedheader))) {
        if (runtime->m_status == "Yado") {
            if (!is_expanding())
                _create_yadomoney({scale(10), scale(6)});
            if (showbuttons) {
                auto button = std::make_shared<CancelButton>();
                button->initialize(self, {scale(133), scale(6)});
                retain_sprite(this, button);
            }
            if (has_party()) {
                _create_partymoney(panel_position);
                rmargin += scale(34);
                if (m_partymoney)
                    left -= panel_width + panel_gap;
            }
        } else {
            Integer left2 = scale(10);
            if (runtime->is_battlestatus() && runtime->m_setting &&
                runtime->m_setting->m_show_roundautostartbutton) {
                _create_autostart({scale(5), scale(3)});
                left2 = scale(36);
            }
            if (showbuttons) {
                auto button = std::make_shared<CancelButton>();
                button->initialize(self, {left2, scale(6)});
                retain_sprite(this, button);
            }
            if (runtime->is_battlestatus()) {
                auto panel2 = std::make_shared<RoundCounterPanel>();
                panel2->initialize(self, {scale(474) - rmargin, scale(6)});
                retain_sprite(this, panel2);
                rmargin += scale(34);
                left -= panel_width + panel_gap;
            } else if (runtime->m_status == "Scenario") {
                _create_partymoney(panel_position);
                rmargin += scale(34);
                if (m_partymoney)
                    left -= panel_width + panel_gap;
            }
        }
    } else if (runtime && runtime->m_status == "Yado") {
        if (!is_expanding())
            _create_yadomoney({scale(10), scale(6)});
        if (has_party()) {
            _create_partymoney(panel_position);
            rmargin += scale(34);
            if (m_partymoney)
                left -= panel_width + panel_gap;
        }
    } else if (runtime && runtime->m_status == "Scenario") {
        if (showbuttons) {
            auto camp = std::make_shared<CampButton>();
            camp->initialize(self, {scale(10), scale(6)});
            retain_sprite(this, camp);
            auto table = std::make_shared<TableButton>();
            table->initialize(self, {scale(133), scale(6)});
            retain_sprite(this, table);
        }
        _create_partymoney(panel_position);
        rmargin += scale(34);
        if (m_partymoney)
            left -= panel_width + panel_gap;
        if (showbuttons && runtime->is_playingscenario() && data && data->has_infocards())
            _create_infocards({scale(474) - rmargin, scale(3)});
    } else if (runtime && runtime->is_battlestatus() && !runtime->m_battle) {
        auto panel = std::make_shared<EncounterPanel>();
        panel->initialize(self, panel_position);
        retain_sprite(this, panel);
        left -= panel_width + panel_gap;
    } else if (runtime && runtime->is_battlestatus() && runtime->m_battle && *runtime->m_battle) {
        Integer left2 = scale(10);
        if (runtime->m_setting && runtime->m_setting->m_show_roundautostartbutton) {
            _create_autostart({scale(5), scale(3)});
            left2 = scale(36);
        }
        if (showbuttons) {
            auto action = std::make_shared<ActionButton>();
            action->initialize(self, {left2, scale(6)});
            retain_sprite(this, action);
            if (m_autostart && *m_autostart)
                (*m_autostart)->m_actionbtn = action;
            if ((*runtime->m_battle)->m_possible_runaway && data &&
                data->m_party_environment_runaway) {
                auto runaway = std::make_shared<RunAwayButton>();
                runaway->initialize(self, {scale(123) + left2, scale(6)});
                retain_sprite(this, runaway);
            }
        }
        auto panel = std::make_shared<RoundCounterPanel>();
        panel->initialize(self, {scale(474) - rmargin, scale(6)});
        retain_sprite(this, panel);
        left -= panel_width + panel_gap;
        rmargin += scale(34);
        if (showbuttons && runtime->is_debugmode() && (*runtime->m_battle)->is_ready() &&
            has_friend_cards())
            _create_friendcards({scale(474) - rmargin, scale(3)});
    }

    if (runtime && runtime->m_setting && runtime->m_setting->m_show_debuglogdialog &&
        !runtime->is_playingscenario() && runtime->is_debugmode() && data &&
        data->m_debuglog && !runtime->m_is_decompressing) {
        left -= button_step;
        _create_debuglog({left, scale(3)});
    }

    if (m_infocards && *m_infocards && runtime && !runtime->is_playingscenario())
        (*m_infocards)->set_notice(false);
    if (m_debuglog && *m_debuglog && runtime &&
        !( !runtime->is_playingscenario() && runtime->is_debugmode() && data && data->m_debuglog))
        (*m_debuglog)->set_notice(false);

    if (showbuttons)
        m_loading = false;

    if (!data || !data->m_in_f9) {
        if (runtime && runtime->m_event)
            runtime->m_event->refresh_tools();
    }

    update_tiles();
    invalidate_rect(m_rect);
}

void StatusBar::clear()
{
    const auto old = m_rect;
    for (const auto& object : m_status_items)
        unregister_statusbar_sprite(object);
    for (const auto& object : m_status_progress)
        unregister_statusbar_sprite(object);
    hide_all_status_bar_descs(*this);
    // Python の clear() と同様、STATUS_ITEM/STATUS_PROGRESS/DESC
    // だけを除く。 タッチメニューのタイルは hide_touchbuttons() を明示的に呼ぶまで残す。
    remove_backend_layer(g_LAYER_STATUS_ITEM);
    remove_backend_layer(g_LAYER_STATUS_PROGRESS);
    remove_backend_layer(g_LAYER_DESC);
    m_status_items.clear();
    m_status_progress.clear();
    invalidate_rect(old);
}

void StatusBar::hide_descs()
{
    // Python/wx は一つのイベントループ内で、モーダル終了イベン
    // トの処理中に Desc を除く。 C++ の UI・ゲーム分離では
    // 、入力再開前のゲーム側の終了処理として、同じ操作を明示的に行う。
    hide_all_status_bar_descs(*this);
    // バーの再構築で所有ボタンが置き換わっても、古い Desc のプロキシ
    // ーが残る場合がある。 Python の group.remove(old_desc)
    // と同様、所有者を失ったプロキシーも直ちに除く。
    for (const auto& object : m_status_items) {
        if (!std::dynamic_pointer_cast<Desc>(object)) continue;
        if (const auto sprite = std::dynamic_pointer_cast<::cw::sprite::base::CWPySprite>(object))
            invalidate_rect(sprite->m_rect);
        unregister_statusbar_sprite(object);
    }
    m_status_items.erase(
        std::remove_if(m_status_items.begin(), m_status_items.end(), [](const auto& object) {
            return static_cast<bool>(std::dynamic_pointer_cast<Desc>(object));
        }),
        m_status_items.end());
    remove_backend_layer(g_LAYER_DESC);
}

