bool CampButton::uses_click_animation() const
{
    // Python の CampButton と同様、特殊エリアを直接変更する。 固有の
    // update() は StatusBarButton のクリック状態を進めない。
    return false;
}

void CampButton::on_activate()
{
    if (!::cw::g_cwpy)
        return;
    if (::cw::g_cwpy->m_statusbar_area_switching.exchange(true)) return;
    try {
        if (::cw::g_cwpy->m_areaid >= 0) {
            play_status_sound("click");
            ::cw::g_cwpy->change_specialarea(-4, false);
        } else if (::cw::g_cwpy->m_areaid == -4) {
            play_status_sound("click");
            ::cw::g_cwpy->clear_specialarea(true, false);
        }
    } catch (...) {
        ::cw::g_cwpy->m_statusbar_area_switching = false;
        throw;
    }
    // change_specialarea()/clear_specialarea()
    // はゲームスレッドで同期的に完了する。 Python と同様、新エリアが準
    // 備済みの状態で戻り、ボタン解除だけのために USEREVENT を予約し
    // ない。 解除を遅らせると、その処理まで is_lockmenucards()
    // が全キャンプカードを遮り、入れ子のループでさらに遅れる場合がある。
    ::cw::g_cwpy->m_statusbar_area_switching = false;
}

