void EncounterPanel::update(const ::cw::lib::Arguments& arg_args, const ::cw::lib::KeywordArguments& arg_kwargs)
{
    (void)arg_args;
    (void)arg_kwargs;
    const auto text = message_text("encounter", "encounter");
    if (!m_text || *m_text != text) {
        m_text = text;
        update_image();
    }
}

void EncounterPanel::update_image()
{
    const auto text_image = get_scaledimage(render_panel_text(message_text("encounter", "encounter")));
    auto image = copy_surface(m_panelimg_typed);
    if (!image) return;
    const auto& rect = ::cw::sprite::base::MouseHandlerSprite::m_rect;
    blit_surface(image, text_image, panel_half(rect.width - text_image->size.width),
                 panel_half(rect.height - text_image->size.height));
    ::cw::sprite::base::MouseHandlerSprite::m_image = image;
    m_image = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
    invalidate_rect(rect);
}

