void TouchMenuButton::update(const ::cw::lib::Arguments& arg_args, const ::cw::lib::KeywordArguments& arg_kwargs)
{
    ::cw::sprite::base::SelectableSprite::update_selection();
    m_is_pushed = m_touchbuttons_visible;
    StatusBarButton::m_is_pushed = m_is_pushed;
    StatusBarButton::set_desc(m_is_pushed ? "" : message_text("desc_touch_menu", "touch menu"));
    StatusBarButton::update_image();
    (void)arg_args;
    (void)arg_kwargs;
}

bool TouchMenuButton::uses_click_animation() const
{
    // Python と同様、タッチ操作部品を直接開閉し、基底のクリックアニメー
    // ションへ入らない。 固有の update() は開閉状態だけを維持する。
    return false;
}

std::tuple<::cw::lib::Real, std::map<::cw::lib::String, ::cw::lib::String>, std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::Integer, bool, bool, bool>, std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::Integer, bool, bool, bool>, std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::Integer, bool, bool, bool>> TouchMenuButton::_upscrmemo()
{
    std::map<::cw::lib::String, ::cw::lib::String> basefont;
    std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::Integer, bool, bool, bool> desc{};
    std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::Integer, bool, bool, bool> title{};
    std::tuple<::cw::lib::String, ::cw::lib::String, ::cw::lib::Integer, bool, bool, bool> progress{};
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting) {
        basefont = ::cw::g_cwpy->m_setting->get_basefont();
        const auto fonts = ::cw::g_cwpy->m_setting->get_fonttypes();
        if (const auto it = fonts.find("sbardesc"); it != fonts.end()) desc = it->second;
        if (const auto it = fonts.find("sbardesctitle"); it != fonts.end()) title = it->second;
        if (const auto it = fonts.find("sbarprogress"); it != fonts.end()) progress = it->second;
    }
    return {::cw::g_UP_SCR, std::move(basefont), desc, title, progress};
}

void TouchMenuButton::on_activate()
{
    play_status_sound("page");
    m_is_pushed = m_touchbuttons_visible;
    StatusBarButton::m_is_pushed = m_is_pushed;

    if (m_is_pushed) {
        StatusBarButton::set_desc(message_text("desc_touch_menu", "touch menu"));
        const auto old = static_cast<::cw::sprite::base::SelectableSprite&>(*this).m_rect;
        for (const auto& object : m_touchbuttons_typed)
            if (const auto sprite = std::dynamic_pointer_cast<::cw::sprite::base::CWPySprite>(object))
                invalidate_rect(sprite->m_rect);
        m_touchbuttons_visible = false;
        m_is_pushed = false;
        StatusBarButton::m_is_pushed = false;
        remove_backend_layer(g_LAYER_TOUCH_BUTTON);
        for (const auto& object : m_touchbuttons_typed)
            unregister_statusbar_sprite(object);
        invalidate_rect(old);
        return;
    }

    StatusBarButton::set_desc("");
    const auto cachekey = _upscrmemo();
    if (!m__cachekey || *m__cachekey != cachekey) {
        for (const auto& object : m_touchbuttons_typed)
            unregister_statusbar_sprite(object);
        m_touchbuttons_typed.clear();
        m__touchbuttons.clear();
        m__cachekey = cachekey;
    }
    if (m_touchbuttons_typed.empty()) {
        static ::cw::sprite::touchbutton::TouchRuntimeContext context;
        context = {};
        context.hide_touchbuttons = [] {
            if (::cw::g_cwpy && ::cw::g_cwpy->m_statusbar)
                ::cw::g_cwpy->m_statusbar->hide_touchbuttons(true);
        };
        context.update_tiles = [] {
            if (::cw::g_cwpy && ::cw::g_cwpy->m_statusbar)
                ::cw::g_cwpy->m_statusbar->update_tiles();
        };
        context.can_select = [] { return ::cw::sprite::touchbutton::can_selectsprite(); };
        ::cw::sprite::touchbutton::set_runtime_context(&context);

        const auto width_for = [](const ::cw::lib::String& name, const ::cw::lib::String& desc,
                                  const ::cw::lib::String& hotkey) {
            return ::cw::sprite::touchbutton::TouchButton::calc_width(std::nullopt, name, desc, hotkey);
        };
        const auto f4_name = message_text("switch_expanded_mode", "switch expanded mode");
        const auto f4_desc = message_text("desc_switch_expanded_mode", "switch expanded mode");
        const auto ss_name = message_text("screenshot", "screenshot");
        const auto ss_desc = message_text("desc_screenshot", "screenshot");
        const auto ssh_name = message_text("screenshot_hands", "card screenshot");
        const auto ssh_desc = message_text("desc_screenshot_hands", "card screenshot");
        const auto copy_name = message_text("copy_text", "copy text");
        const auto copy_desc = message_text("desc_copy_text", "copy text");
        const auto instructions_name = message_text("instructions", "instructions");
        const auto instructions_desc = message_text("desc_instructions", "instructions");
        const auto f9_name = message_text("f9", "F9");
        const auto f9_desc = message_text("desc_f9", "F9");
        const auto debug_name = message_text("toggle_debug_mode", "toggle debug mode");
        const auto debug_desc = message_text("desc_toggle_debug_mode", "toggle debug mode");
        Integer bw = scale(150);
        bw = std::max({bw, width_for(f4_name, f4_desc, "F4"), width_for(ss_name, ss_desc, "PrtScn"),
                       width_for(ssh_name, ssh_desc, "Shift+PrtScn"), width_for(copy_name, copy_desc, "Ctrl+C"),
                       width_for(instructions_name, instructions_desc, "F8"), width_for(f9_name, f9_desc, "F9"),
                       width_for(debug_name, debug_desc, "Ctrl+D")});

        auto add_button = [this](const std::shared_ptr<::cw::sprite::touchbutton::TouchButton>& button,
                                 Integer left, Integer shift_top, Integer top) {
            button->m_rect.x = left;
            button->m_rect.y = top;
            button->m_shift_top = shift_top;
            m_touchbuttons_typed.push_back(std::static_pointer_cast<::cw::lib::Object>(button));
            m__touchbuttons.emplace_back(std::static_pointer_cast<::cw::lib::Object>(button));
        };
        const Integer area_right = scale(std::get<0>(::cw::g_SIZE_AREA));
        const Integer area_bottom = scale(std::get<1>(::cw::g_SIZE_AREA));
        const Integer left = area_right - bw;
        std::vector<std::shared_ptr<::cw::sprite::touchbutton::TouchButton>> buttons;
        const auto enable_true = callback_bool([] { return true; });
        auto f4 = std::make_shared<::cw::sprite::touchbutton::TouchButton>();
        f4->initialize(std::nullopt, f4_name, f4_desc, "F4", callback_void(TouchMenuButton_lclick_event_f4), enable_true, bw);
        auto screenshot = std::make_shared<::cw::sprite::touchbutton::TouchButton>();
        screenshot->initialize(std::nullopt, ss_name, ss_desc, "PrtScn", callback_void([] { ::cw::util::screenshot(); }), enable_true, bw);
        auto cardshot = std::make_shared<::cw::sprite::touchbutton::TouchButton>();
        cardshot->initialize(std::nullopt, ssh_name, ssh_desc, "Shift+PrtScn", callback_void([] { ::cw::util::card_screenshot(); }),
                             callback_bool([] { return ::cw::g_cwpy && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata &&
                                                       (*::cw::g_cwpy->m_ydata)->m_party.has_value(); }), bw);
        auto copy = std::make_shared<::cw::sprite::touchbutton::TouchButton>();
        copy->initialize(std::nullopt, copy_name, copy_desc, "Ctrl+C", callback_void(TouchMenuButton_lclick_event_copy_text),
                         callback_bool([] { return TouchMenuButton_lclick_event_copybtn_enabled(); }), bw);
        auto instructions = std::make_shared<::cw::sprite::touchbutton::TouchButton>();
        instructions->initialize(std::nullopt, instructions_name, instructions_desc, "F8", callback_void(TouchMenuButton_lclick_event_f8),
                                 callback_bool([] { return TouchMenuButton_lclick_event_has_instructions(); }), bw);
        auto f9 = std::make_shared<::cw::sprite::touchbutton::TouchButton>();
        f9->initialize(std::nullopt, f9_name, f9_desc, "F9", callback_void(TouchMenuButton_lclick_event_f9),
                       callback_bool([] { return ::cw::eventhandler::EventHandler::can_f9(); }), bw);
        buttons = {f4, screenshot, cardshot, copy, instructions};
        // Novel モードは Py にないネイティブ拡張であり、ハンドラーが F9 とデ
        // バッグモードを拒否する。 利用できないそれらの操作は、この UI にも出さない。
        if (!::cw::novel::enabled()) {
            buttons.push_back(f9);
            auto debug = std::make_shared<::cw::sprite::touchbutton::TouchButton>();
            debug->initialize(std::nullopt, debug_name, debug_desc, "Ctrl+D", callback_void(TouchMenuButton_lclick_event_debug_mode),
                              callback_bool([] { return true; }), bw);
            buttons.push_back(debug);
        }
        auto volume = std::make_shared<::cw::sprite::touchbutton::VolumeTile>();
        volume->initialize(bw);
        buttons.push_back(volume);
        Integer top = area_bottom;
        for (auto it = buttons.rbegin(); it != buttons.rend(); ++it) {
            top -= (*it)->m_rect.height;
            add_button(*it, left, top, area_bottom);
        }

        const Integer lbtn_w = bw / 32 * 7;
        const Integer rclick_w = bw / 32 * 8;
        const Integer rbtn_w = bw / 32 * 7;
        const Integer lclick_w = bw - lbtn_w - rclick_w - rbtn_w;
        Integer tile_left = left;
        auto left_tile = std::make_shared<::cw::sprite::touchbutton::SwitchSpriteTile>();
        left_tile->initialize(icon_placeholder("SWITCH_TO_LEFT", {80, 80, 100, 255}), -1, lbtn_w);
        top -= left_tile->m_rect.height;
        add_button(left_tile, tile_left, top, area_bottom);
        tile_left += lbtn_w;
        auto left_click = std::make_shared<::cw::sprite::touchbutton::SimplePointableTile>();
        left_click->initialize(icon_placeholder("TOUCH_LCLICK", {80, 130, 90, 255}), message_text("touch_lclick", "left click"),
                               callback_void(TouchMenuButton_lclick_event_lclick),
                               callback_bool([] { return ::cw::sprite::touchbutton::can_selectsprite() && ::cw::g_cwpy &&
                                                         ::cw::g_cwpy->m_index != -1; }), lclick_w);
        add_button(left_click, tile_left, top, area_bottom);
        tile_left += lclick_w;
        auto right_click = std::make_shared<::cw::sprite::touchbutton::SimplePointableTile>();
        right_click->initialize(icon_placeholder("TOUCH_RCLICK", {130, 90, 80, 255}), message_text("touch_rclick", "right click"),
                                callback_void(TouchMenuButton_lclick_event_rclick),
                                callback_bool([] { return ::cw::g_cwpy && !::cw::g_cwpy->is_showingmessage() &&
                                                         ::cw::sprite::touchbutton::can_selectsprite() && ::cw::g_cwpy->m_index != -1; }), rclick_w);
        add_button(right_click, tile_left, top, area_bottom);
        tile_left += rclick_w;
        auto right_tile = std::make_shared<::cw::sprite::touchbutton::SwitchSpriteTile>();
        right_tile->initialize(icon_placeholder("SWITCH_TO_RIGHT", {80, 80, 100, 255}), 1, rbtn_w);
        add_button(right_tile, tile_left, top, area_bottom);
        add_backend_layer(g_LAYER_TOUCH_BUTTON, m_touchbuttons_typed);
    }
    if (!m_touchbuttons_typed.empty()) {
        m_touchbuttons_visible = true;
        m_is_pushed = true;
        StatusBarButton::m_is_pushed = true;
        for (const auto& object : m_touchbuttons_typed) {
            const auto sprite = std::dynamic_pointer_cast<::cw::sprite::touchbutton::TouchButton>(object);
            if (!sprite)
                continue;
            sprite->m_rect.y = scale(std::get<1>(::cw::g_SIZE_AREA));
            sprite->update_selection();
            ::cw::animation::start_animation(sprite, "shiftup");
        }
    }
    add_backend_layer(g_LAYER_TOUCH_BUTTON, m_touchbuttons_typed);
    for (const auto& object : m_touchbuttons_typed) {
        // Python と同様、タッチタイルは非表示中に sbargrp か
        // ら外し、メニューを開く時に再追加する。 開くたびにキャッシュ済み
        // インスタンスを再登録し、バックエンドのプロキシーを重複させない。
        unregister_statusbar_sprite(object);
        register_statusbar_sprite(object);
        if (const auto sprite = std::dynamic_pointer_cast<::cw::sprite::touchbutton::TouchButton>(object))
            invalidate_rect(sprite->m_rect);
    }
}

