{
    return icon_placeholder("MONEYY", {180, 180, 0, 255});
}

bool YadoMoneyPanel::need_update(::cw::lib::String arg_text, ::cw::lib::String arg_currency)
{
    return !m_text || *m_text != arg_text || m_currency != arg_currency || m_up_scr != ::cw::g_UP_SCR;
}

void YadoMoneyPanel::put_updatekey(::cw::lib::String arg_text, ::cw::lib::String arg_currency)
{
    m_text = std::move(arg_text);
    m_currency = std::move(arg_currency);
    m_up_scr = ::cw::g_UP_SCR;
}

void YadoMoneyPanel::update(const ::cw::lib::Arguments& arg_args, const ::cw::lib::KeywordArguments& arg_kwargs)
{
    StatusBarPanel::update(arg_args, arg_kwargs);
    if (::cw::sprite::base::CWPySprite::m_status == "blink")
        return;
    const auto currency = message_text("currency", "%s");
    if (need_update(get_money(), currency)) {
        put_updatekey(get_money(), currency);
        update_image();
    }
}

::cw::lib::String YadoMoneyPanel::get_money()
{
    return ::cw::g_cwpy && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata ?
        std::to_string((*::cw::g_cwpy->m_ydata)->m_money) : "0";
}

void YadoMoneyPanel::update_image()
{
    StatusBarPanel::update_image();
    const auto formatted = ::cw::lib::python_percent_string(m_currency, m_text.value_or("None"));
    const auto text_image = get_scaledimage(render_panel_text(formatted));
    auto image = copy_surface(m_panelimg_typed);
    if (!image) return;
    const auto& rect = ::cw::sprite::base::MouseHandlerSprite::m_rect;
    // Py との意図的な差。残高が七桁を超える場合、右余白を 2px にする。それ以外は
    // Py と同じ 5px。文字の縮小は共通の get_scaledimage で行う。
    const Integer inset = scale(m_text && m_text->size() > 7 ? 2 : 5);
    blit_surface(image, text_image, rect.width - (text_image->size.width + inset),
                 panel_half(rect.height - text_image->size.height));
    ::cw::sprite::base::MouseHandlerSprite::m_image = image;
    m_image = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(image));
    invalidate_rect(rect);
}

void YadoMoneyPanel::update_color()
{
    // Py と同様、ここでは既存のパネル色を変えない。 特に継承した RoundCounterPanel
    // のリセットでも青い背景を維持する。
}

void YadoMoneyPanel::update_blink()
{
    if (m_frame >= 30 || !(::cw::g_cwpy && ::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_blink_partymoney)) {
        ::cw::sprite::base::CWPySprite::m_status = m_old_status;
        m_frame = 0;
        put_updatekey(get_money(), message_text("currency", "%s"));
        update_image();
        return;
    }
    const auto text = (m_frame / 5 % 2 == 1) ? ::cw::lib::String{} : get_money();
    const auto currency = (m_frame / 5 % 2 == 1) ? ::cw::lib::String{"%s"} : message_text("currency", "%s");
    if (need_update(text, currency)) {
        update_color();
        put_updatekey(text, currency);
        update_image();
    }
}

